/**
 * Take the first or last {$limit} characters.
 *
 * @param  int  $limit
 * @return static
 */
public function take(int $limit)
{
    if ($limit < 0) {
        return $this->substr($limit);
    }

    return $this->substr(0, $limit);
}

/**
 * Trim the string of the given characters.
 *
 * @param  string  $characters
 * @return static
 */
public function trim($characters = null)
{
    return new static($this->performTrim($characters, 'both'));
}

/**
 * Left trim the string of the given characters.
 *
 * @param  string  $characters
 * @return static
 */
public function ltrim($characters = null)
{
    return new static($this->performTrim($characters, 'left'));
}

/**
 * Right trim the string of the given characters.
 *
 * @param  string  $characters
 * @return static
 */
public function rtrim($characters = null)
{
    return new static($this->performTrim($characters, 'right'));
}

/**
 * Strip characters from the edges of the underlying string.
 *
 * @param  string|null  $characters
 * @param  string  $side
 * @return string
 */
protected function performTrim($characters, $side)
{
    if ($characters !== null) {
        return match ($side) {
            'left' => ltrim($this->value, $characters),
            'right' => rtrim($this->value, $characters),
            default => trim($this->value, $characters),
        };
    }

    $marks = new HtmlString($this->value);

    $invisible = $marks->byteOrderMark()
        .$marks->zeroWidthSpace()
        .$marks->leftToRightMark()
        .$marks->space()
        .$marks->lineFeed()
        .$marks->carriageReturn()
        .$marks->horizontalTab();

    $pattern = match ($side) {
        'left' => '~^[\s'.$invisible.']+~'.$this->unicode,
        'right' => '~[\s'.$invisible.']+$~'.$this->unicode,
        default => '~^[\s'.$invisible.']+|[\s'.$invisible.']+$~'.$this->unicode,
    };

    $fallback = match ($side) {
        'left' => ltrim($this->value),
        'right' => rtrim($this->value),
        default => trim($this->value),
    };

    return preg_replace($pattern, '', $this->value) ?? $fallback;
}

/**
 * Make a string's first character lowercase.
 *
 * @return static
 */
public function lcfirst()
{
    return new static(Str::lcfirst($this->value));
}

